//! The decoder against the LLVM assembler.
//!
//! `tests/fixtures/a64_corpus.tsv` was generated by `llvm-mc` — assembled from real source, then
//! disassembled to get the canonical mnemonic that tool itself prints. Nothing in it was typed by
//! hand, so a disagreement is a decoder bug and not a stale expectation.
//!
//! The corpus covers each instruction class this decoder claims. A field-level test for the
//! offsets follows, because two decoders can agree on "b" and disagree on where it jumps.

use vitrine::a64::{self, AddressMode, Cond, Instr, MovOp, ShiftType};

fn corpus() -> Vec<(u32, String, String)> {
    let raw = include_str!("fixtures/a64_corpus.tsv");
    raw.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            let mut f = l.split('\t');
            let word = u32::from_str_radix(f.next().unwrap().trim_start_matches("0x"), 16).unwrap();
            let mnemonic = f.next().unwrap().to_string();
            let asm = f.next().unwrap_or("").to_string();
            (word, mnemonic, asm)
        })
        .collect()
}

#[test]
fn every_corpus_instruction_decodes_to_the_assemblers_mnemonic() {
    let mut failures = Vec::new();
    for (word, expected, asm) in corpus() {
        let got = a64::decode(word).mnemonic();
        if got != expected {
            let d = a64::decode(word);
            failures.push(format!("{word:#010x} `{asm}`: expected `{expected}`, got `{got}` ({d:?})"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} instructions disagree with llvm-mc:\n{}",
        failures.len(),
        corpus().len(),
        failures.join("\n")
    );
}

#[test]
fn no_corpus_instruction_falls_through_to_unknown() {
    for (word, expected, asm) in corpus() {
        assert!(
            !matches!(a64::decode(word), Instr::Unknown { .. }),
            "{word:#010x} `{asm}` is unimplemented but the corpus expects `{expected}`"
        );
    }
}

// -- fields, not just names ------------------------------------------------

#[test]
fn branch_offsets_are_signed_and_scaled() {
    assert_eq!(a64::decode(0x1400_0040), Instr::B { offset: 0x100 });
    assert_eq!(a64::decode(0x9400_0080), Instr::Bl { offset: 0x200 });
    // b.ne #-4 — the only negative branch in the corpus, and the one a wrong sign breaks.
    assert_eq!(
        a64::decode(0x54FF_FFE1),
        Instr::BCond {
            cond: Cond::Ne,
            offset: -4
        }
    );
    // tbnz w5, #31 — the bit number is split across two fields.
    assert_eq!(
        a64::decode(0x37F8_0085),
        Instr::Tbz {
            nonzero: true,
            rt: 5,
            bit: 31,
            offset: 16
        }
    );
}

#[test]
fn adr_and_adrp_carry_their_real_offsets() {
    assert_eq!(
        a64::decode(0x1000_0106),
        Instr::Adr {
            rd: 6,
            offset: 0x20
        }
    );
    // adrp x7, #0x4000: the immediate is encoded as a page number, not a byte offset.
    assert_eq!(
        a64::decode(0x9000_0027),
        Instr::Adrp {
            rd: 7,
            page_offset: 0x4000
        }
    );
}

#[test]
fn mov_variants_are_distinguished() {
    assert_eq!(
        a64::decode(0xD282_4688),
        Instr::Mov {
            sf: true,
            op: MovOp::Zero,
            rd: 8,
            imm16: 0x1234,
            shift: 0
        }
    );
    assert_eq!(
        a64::decode(0xF2A0_002A),
        Instr::Mov {
            sf: true,
            op: MovOp::Keep,
            rd: 10,
            imm16: 1,
            shift: 16
        }
    );
}

#[test]
fn add_sub_immediate_keeps_width_and_shift() {
    assert_eq!(
        a64::decode(0x9100_418B),
        Instr::AddSubImm {
            sf: true,
            sub: false,
            set_flags: false,
            rd: 11,
            rn: 12,
            imm: 0x10,
            lsl12: false
        }
    );
    assert_eq!(
        a64::decode(0xD100_21CD),
        Instr::AddSubImm {
            sf: true,
            sub: true,
            set_flags: false,
            rd: 13,
            rn: 14,
            imm: 8,
            lsl12: false
        }
    );
}

#[test]
fn shifted_register_operands_keep_their_shift_and_amount() {
    assert_eq!(
        a64::decode(0x0B11_0A0F),
        Instr::AddSubShifted {
            sf: false,
            sub: false,
            set_flags: false,
            rd: 15,
            rn: 16,
            rm: 17,
            shift: ShiftType::Lsl,
            amount: 2
        }
    );
    assert_eq!(
        a64::decode(0x4B54_0E72),
        Instr::AddSubShifted {
            sf: false,
            sub: true,
            set_flags: false,
            rd: 18,
            rn: 19,
            rm: 20,
            shift: ShiftType::Lsr,
            amount: 3
        }
    );
}

#[test]
fn load_store_modes_are_not_flattened() {
    // ldr x4, [x5] — unsigned offset 0
    assert_eq!(
        a64::decode(0xF940_00A4),
        Instr::LoadStore {
            load: true,
            size: 8,
            signed: false,
            rt: 4,
            rn: 5,
            mode: AddressMode::Offset { imm: 0 }
        }
    );
    // str w8, [x9, #-4] — this is an *unscaled* store, i.e. STUR, not a negative unsigned offset.
    assert_eq!(
        a64::decode(0xB81F_C128),
        Instr::LoadStore {
            load: false,
            size: 4,
            signed: false,
            rt: 8,
            rn: 9,
            mode: AddressMode::Unscaled { imm: -4 }
        }
    );
    // ldp w16, w17, [x18], #8 — post-index, base written back.
    assert_eq!(
        a64::decode(0x28C1_4650),
        Instr::LoadStorePair {
            load: true,
            sf: false,
            rt: 16,
            rt2: 17,
            rn: 18,
            mode: AddressMode::PostIndex { imm: 8 }
        }
    );
}

#[test]
fn register_offset_carries_extend_and_scaling_not_a_shift() {
    // ldr x10, [x11, x12] — option 011 (LSL), S = 0.
    assert_eq!(
        a64::decode(0xF86C_696A),
        Instr::LoadStore {
            load: true,
            size: 8,
            signed: false,
            rt: 10,
            rn: 11,
            mode: AddressMode::RegisterOffset {
                rm: 12,
                extend: 3,
                scaled_by_size: false
            }
        }
    );
}

#[test]
fn svc_carries_its_immediate() {
    assert_eq!(a64::decode(0xD400_0001), Instr::Svc { imm: 0 });
}

#[test]
fn system_register_access_is_decoded_not_guessed() {
    assert_eq!(
        a64::decode(0xD53B_D040),
        Instr::Mrs {
            rt: 0,
            sysreg: 0xDE82
        }
    );
    assert_eq!(
        a64::decode(0xD51B_D041),
        Instr::Msr {
            sysreg: 0xDE82,
            rt: 1
        }
    );
}

// -- behaviour the recompiler depends on -----------------------------------

#[test]
fn block_terminators_are_identified() {
    for word in [0x1400_0040, 0xD61F_0000, 0xD65F_03C0, 0xD63F_0020] {
        assert!(
            a64::decode(word).ends_block(),
            "{word:#010x} must end a basic block"
        );
    }
    for word in [0x9400_0080, 0xD503_201F, 0x9100_418B] {
        assert!(
            !a64::decode(word).ends_block(),
            "{word:#010x} must not end a basic block"
        );
    }
}

#[test]
fn calls_are_distinguished_from_jumps() {
    assert!(a64::decode(0x9400_0080).is_call(), "bl is a call");
    assert!(a64::decode(0xD63F_0020).is_call(), "blr is a call");
    assert!(!a64::decode(0x1400_0040).is_call(), "b is not a call");
    assert!(!a64::decode(0xD61F_0000).is_call(), "br is not a call");
}

#[test]
fn an_unimplemented_instruction_is_reported_not_invented() {
    // A vector load, which this decoder deliberately does not cover yet.
    let word = 0x3DC0_0000u32;
    match a64::decode(word) {
        Instr::Unknown { word: w } => assert_eq!(w, word),
        other => panic!("expected Unknown, got {other:?}"),
    }
}

#[test]
fn every_instruction_in_compiler_output_is_recognised() {
    // Words harvested from clang -O0/-O2/-Os aarch64 output and stored in programs.tsv. This is the
    // honest coverage claim: these are instructions a real compiler emitted, not random words and
    // not instructions chosen because they are easy.
    let raw = include_str!("fixtures/programs.tsv");
    let mut checked = 0;
    let mut unknown = Vec::new();
    for line in raw.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut f = line.split('\t');
        let name = f.next().expect("name");
        if !name.starts_with("real_code_") {
            continue;
        }
        for w in f.next().expect("words").split_whitespace() {
            let word = u32::from_str_radix(w.trim_start_matches("0x"), 16).expect("hex");
            checked += 1;
            if matches!(a64::decode(word), Instr::Unknown { .. }) {
                unknown.push(word);
            }
        }
    }
    assert!(checked > 200, "expected a few hundred real instructions, got {checked}");
    assert!(
        unknown.is_empty(),
        "{} of {checked} real instructions are unrecognised: {:08x?}",
        unknown.len(),
        unknown
    );
}
